// Slug → headline for the per-post Open Graph card
// (app/blog/[slug]/opengraph-image.tsx). Derived from `articles` rather than
// restated, so a share card can never drift from the post it represents.
export const articleOgTitles: Record<string, string> = Object.fromEntries(
  Object.entries(articles).map(([slug, article]) => [slug, article.title]),
);
